import{_ as i,o as t,c as l,a2 as e}from"./chunks/framework.BXzK3EA4.js";const c=JSON.parse('{"title":"05 Codex 自动化","description":"","frontmatter":{"title":"05 Codex 自动化"},"headers":[],"relativePath":"前端/engineering/ai-copilot/05-codex-自动化.md","filePath":"前端/engineering/ai-copilot/05-codex-自动化.md","lastUpdated":1792894072000}'),o={name:"前端/engineering/ai-copilot/05-codex-自动化.md"};function s(n,a,r,d,h,p){return t(),l("div",null,[...a[0]||(a[0]=[e(`<h1 id="_05-codex-自动化" tabindex="-1">05 Codex 自动化 <a class="header-anchor" href="#_05-codex-自动化" aria-label="Permalink to &quot;05 Codex 自动化&quot;">​</a></h1><blockquote><p>用 Codex Automate 和 /loop 实现工程任务自动化，让 AI 帮你监控 CI、依赖更新、发布状态。</p></blockquote><nav class="table-of-contents"><ul><li><a href="#_5-1-自动化能做什么">5.1 自动化能做什么</a></li><li><a href="#_5-2-codex-automate-定时任务">5.2 Codex Automate（定时任务）</a><ul><li><a href="#创建-automate-的标准流程">创建 Automate 的标准流程</a></li><li><a href="#示例-1-每周依赖版本检查">示例 1：每周依赖版本检查</a></li><li><a href="#示例-2-pr-merge-前自动化检查">示例 2：PR Merge 前自动化检查</a></li><li><a href="#示例-3-ci-失败自动分析">示例 3：CI 失败自动分析</a></li></ul></li><li><a href="#_5-3-codex-autopilot-pr-维护">5.3 Codex /autopilot（PR 维护）</a><ul><li><a href="#使用-autopilot">使用 /autopilot</a></li><li><a href="#autopilot-的行为规范">/autopilot 的行为规范</a></li></ul></li><li><a href="#_5-4-codex-loop-定期提醒">5.4 Codex /loop（定期提醒）</a></li><li><a href="#_5-5-自动化安全规则">5.5 自动化安全规则</a></li><li><a href="#下一步">下一步</a></li><li><a href="#面试常考">面试常考</a><ul><li><a href="#q1-codex-automate-什么时候用">Q1:Codex Automate 什么时候用?</a></li><li><a href="#q2-autopilot-做什么">Q2:/autopilot 做什么?</a></li><li><a href="#q3-自动化安全规则">Q3:自动化安全规则?</a></li></ul></li></ul></nav><h2 id="_5-1-自动化能做什么" tabindex="-1">5.1 自动化能做什么 <a class="header-anchor" href="#_5-1-自动化能做什么" aria-label="Permalink to &quot;5.1 自动化能做什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>人工做法</th><th>自动化做法</th></tr></thead><tbody><tr><td><strong>依赖版本检查</strong></td><td>每周手动查一次 npm outdated</td><td>每周 AI 自动查 + 报告 + 评估是否升级</td></tr><tr><td><strong>CI 失败通知</strong></td><td>等 CI 红了才知道</td><td>AI 监控 CI，失败时分析原因 + 报告</td></tr><tr><td><strong>PR 冲突处理</strong></td><td>手动 merge base + 解决冲突</td><td>AI 自动 merge + 解决 + 提交</td></tr><tr><td><strong>发布前检查</strong></td><td>逐条人工检查</td><td>AI 按清单检查，报告异常</td></tr><tr><td><strong>定时健康检查</strong></td><td>无</td><td>每天 AI 检查页面是否可访问</td></tr></tbody></table><h2 id="_5-2-codex-automate-定时任务" tabindex="-1">5.2 Codex Automate（定时任务） <a class="header-anchor" href="#_5-2-codex-automate-定时任务" aria-label="Permalink to &quot;5.2 Codex Automate（定时任务）&quot;">​</a></h2><p>Codex Automate 是 Codex 的自动化任务功能，可以设置：</p><ul><li><strong>触发条件</strong>：定时（cron）、GitHub 事件、Slack 消息、Linear 事件等</li><li><strong>执行内容</strong>：AI Prompt 指令</li><li><strong>通知方式</strong>：邮件 / Slack / 评论等</li></ul><h3 id="创建-automate-的标准流程" tabindex="-1">创建 Automate 的标准流程 <a class="header-anchor" href="#创建-automate-的标准流程" aria-label="Permalink to &quot;创建 Automate 的标准流程&quot;">​</a></h3><ol><li>确定触发条件（什么时候跑？）</li><li>确定任务内容（要做什么？）</li><li>确定通知方式（结果通知谁？）</li><li>测试运行（验证正确性）</li><li>上线监控</li></ol><h3 id="示例-1-每周依赖版本检查" tabindex="-1">示例 1：每周依赖版本检查 <a class="header-anchor" href="#示例-1-每周依赖版本检查" aria-label="Permalink to &quot;示例 1：每周依赖版本检查&quot;">​</a></h3><p>触发：每周一 9:00（cron: 0 9 * * 1）</p><p>任务： 检查 member-h5 项目的依赖更新：</p><ol><li>运行 npm outdated --json</li><li>对比 package.json 和 node_modules 版本</li><li>筛选出有 breaking change 的大版本更新</li><li>评估升级风险（是否影响现有功能）</li><li>输出报告，标注：安全更新 / 功能更新 / 破坏性更新</li></ol><p>通知：Slack #dev-alerts 频道</p><h3 id="示例-2-pr-merge-前自动化检查" tabindex="-1">示例 2：PR Merge 前自动化检查 <a class="header-anchor" href="#示例-2-pr-merge-前自动化检查" aria-label="Permalink to &quot;示例 2：PR Merge 前自动化检查&quot;">​</a></h3><p>触发：PR 检查通过（git_ci 事件）</p><p>任务： PR 合并前做最后一次检查：</p><ol><li>确认构建成功（npm run build）</li><li>确认类型检查通过（tsc --noEmit）</li><li>确认 ESLint 无警告</li><li>确认测试覆盖率没有下降</li><li>确认 CHANGELOG 已更新</li></ol><p>如果有任何一项失败： - 在 PR 下评论说明失败原因 - 给出修复建议 - 标记需要人工介入</p><p>如果全部通过： - PR 下评论：自动检查全部通过，可以合并</p><h3 id="示例-3-ci-失败自动分析" tabindex="-1">示例 3：CI 失败自动分析 <a class="header-anchor" href="#示例-3-ci-失败自动分析" aria-label="Permalink to &quot;示例 3：CI 失败自动分析&quot;">​</a></h3><p>触发：CI 检查失败（git_ci）</p><p>任务： 分析构建失败的根因：</p><ol><li>读取失败的 CI 日志</li><li>找出第一个报错信息</li><li>分析是代码问题还是 CI 本身问题</li><li>如果是代码问题，给出： <ul><li>报错文件 + 行号</li><li>错误原因</li><li>修复建议</li></ul></li><li>在 PR 下评论报告</li></ol><h2 id="_5-3-codex-autopilot-pr-维护" tabindex="-1">5.3 Codex /autopilot（PR 维护） <a class="header-anchor" href="#_5-3-codex-autopilot-pr-维护" aria-label="Permalink to &quot;5.3 Codex /autopilot（PR 维护）&quot;">​</a></h2><p>/autopilot 是 Codex 内置的 PR 维护 Agent，核心功能：</p><ol><li>Merge 冲突：自动 merge base 并解决冲突</li><li>评论审查：处理 PR 上的 Review 评论（fix / dismiss / ask）</li><li>CI 失败：自动修复 CI 问题</li><li>状态汇报：报告当前 PR 状态（可合并 / 阻塞中）</li></ol><h3 id="使用-autopilot" tabindex="-1">使用 /autopilot <a class="header-anchor" href="#使用-autopilot" aria-label="Permalink to &quot;使用 /autopilot&quot;">​</a></h3><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">当前有一个 PR：</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 分支：feature/vip-display</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> base: main</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 问题：CI 红（tsc 报错）、有 2 个未处理的 review comment</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">请用 /autopilot 处理：</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">1.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 先解决冲突（如果有）</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">2.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 修复 tsc 报错</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">3.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 处理 review comment（如果合理就修复，不合理就回复解释）</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">4.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 确保 CI 变绿</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">5.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 最后报告 PR 状态</span></span></code></pre></div><h3 id="autopilot-的行为规范" tabindex="-1">/autopilot 的行为规范 <a class="header-anchor" href="#autopilot-的行为规范" aria-label="Permalink to &quot;/autopilot 的行为规范&quot;">​</a></h3><table tabindex="0"><thead><tr><th>操作</th><th>何时做</th></tr></thead><tbody><tr><td><strong>Fix（修复）</strong></td><td>评论指出了真实问题，在 PR 范围内</td></tr><tr><td><strong>Dismiss（忽略）</strong></td><td>评论无效或已过时，但需要回复说明原因</td></tr><tr><td><strong>Ask（提问）</strong></td><td>安全/隐私/迁移/并发问题，不确定时不猜</td></tr></tbody></table><h2 id="_5-4-codex-loop-定期提醒" tabindex="-1">5.4 Codex /loop（定期提醒） <a class="header-anchor" href="#_5-4-codex-loop-定期提醒" aria-label="Permalink to &quot;5.4 Codex /loop（定期提醒）&quot;">​</a></h2><p>/loop 是在当前 Session 中定期执行一个 Prompt，适合：</p><ul><li>定时检查某个状态（每 5 分钟检查一次 CI 状态）</li><li>监控某个任务进度</li><li>定期给你发状态更新</li></ul><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/loop 5m</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">检查 member-h5 的 CI 状态，如果变绿了就告诉我 CI 已通过</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">如果 30 分钟内还是红的，发通知并停止 loop</span></span></code></pre></div><h2 id="_5-5-自动化安全规则" tabindex="-1">5.5 自动化安全规则 <a class="header-anchor" href="#_5-5-自动化安全规则" aria-label="Permalink to &quot;5.5 自动化安全规则&quot;">​</a></h2><p>AI 自动化有风险，以下规则必须遵守：</p><ol><li>禁止 AI 自动合并 PR（merge 必须人工确认）</li><li>禁止 AI 自动修改 CI 配置文件（只修复代码问题）</li><li>禁止 AI 自动发布到生产（必须人工触发）</li><li>涉及安全的操作（权限/密钥/迁移）必须人工确认</li><li>AI 发现问题时，只报告，不自动执行修复</li></ol><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="./06-多agent">06-多agent</a> — 多 AI Agent 分工协作</li></ul><h2 id="面试常考" tabindex="-1">面试常考 <a class="header-anchor" href="#面试常考" aria-label="Permalink to &quot;面试常考&quot;">​</a></h2><h3 id="q1-codex-automate-什么时候用" tabindex="-1">Q1:Codex Automate 什么时候用? <a class="header-anchor" href="#q1-codex-automate-什么时候用" aria-label="Permalink to &quot;Q1:Codex Automate 什么时候用?&quot;">​</a></h3><p><strong>答</strong>:</p><ul><li><strong>heartbeat</strong>:监控状态(PR CI / 监控面板);状态变化才通知</li><li><strong>cron</strong>:定时任务(日报、清理、轮询)</li><li>原则:不要每分钟刷;只在有意义变化时唤醒</li></ul><h3 id="q2-autopilot-做什么" tabindex="-1">Q2:<code>/autopilot</code> 做什么? <a class="header-anchor" href="#q2-autopilot-做什么" aria-label="Permalink to &quot;Q2:\`/autopilot\` 做什么?&quot;">​</a></h3><p><strong>答</strong>:</p><ul><li>维护 PR 合并就绪</li><li>自动 triage 评论、解决冲突、修 CI</li><li>失败时通知人介入</li><li>适合:CI 长跑、依赖多、需要持续 review 的 PR</li></ul><h3 id="q3-自动化安全规则" tabindex="-1">Q3:自动化安全规则? <a class="header-anchor" href="#q3-自动化安全规则" aria-label="Permalink to &quot;Q3:自动化安全规则?&quot;">​</a></h3><p><strong>答</strong>:</p><ul><li>不能自动推送到 main</li><li>不能自动删除 / 改权限</li><li>不能自动发外部请求(邮件/通知除外)</li><li>所有动作留审计日志</li></ul>`,51)])])}const k=i(o,[["render",s]]);export{c as __pageData,k as default};
